// Navigation Bar Component
// Main header with logo, search, and action buttons

import React, { useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

export const NavigationBar = ({ theme = 'light', onToggleTheme }) => {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState('');
  const [cartCount] = useState(0);
  const [wishlistCount] = useState(0);
  const [showUserMenu, setShowUserMenu] = useState(false);

  const user = useMemo(() => {
    const storedUser = localStorage.getItem('authUser');
    return storedUser ? JSON.parse(storedUser) : null;
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('authUser');
    setShowUserMenu(false);
    navigate('/');
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <div className="logo">
          <h1>Anon</h1>
        </div>

        <div className="search-container">
          <input
            type="text"
            placeholder="Enter your product name..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          <button className="search-btn">🔍</button>
        </div>

        <div className="navbar-actions">
          <button
            className="action-icon"
            title="Toggle theme"
            onClick={onToggleTheme}
            type="button"
          >
            {theme === 'dark' ? '☀️ LIGHT' : '🌙 DARK'}
          </button>
          {user ? (
            <div className="user-menu">
              <button 
                className="action-icon user-name" 
                onClick={() => setShowUserMenu(!showUserMenu)}
                title="Account"
              >
                👤 {user.name}
              </button>
              {showUserMenu && (
                <div className="user-dropdown">
                  <Link to="/products">My Products</Link>
                  <Link to="/order-tracking">My Orders</Link>
                  <button onClick={handleLogout}>Sign Out</button>
                </div>
              )}
            </div>
          ) : (
            <Link className="action-icon" to="/login" title="Account">
              👤 SIGN IN
            </Link>
          )}
          <button className="action-icon wishlist" title="Wishlist">
            ❤️ <span className="badge">{wishlistCount}</span>
          </button>
          <button
            className="action-icon cart"
            title="Cart"
            type="button"
            onClick={() => navigate('/order-tracking')}
          >
            🛒 <span className="badge">{cartCount}</span>
          </button>
        </div>
      </div>

      <div className="secondary-nav">
        <ul className="nav-links">
          <li><Link to="/">HOME</Link></li>
          <li><Link to="/products">CATEGORIES</Link></li>
          <li><Link to="/products">MEN'S</Link></li>
          <li><Link to="/products">WOMEN'S</Link></li>
          <li><Link to="/products">JEWELRY</Link></li>
          <li><Link to="/products">FEATURED</Link></li>
          <li><Link to="/products">BLOG</Link></li>
          <li><Link to="/products">GET OFFER</Link></li>
        </ul>
      </div>
    </nav>
  );
};

export default NavigationBar;
